-- Loader for Delta (XOR encrypted, hidden key)
local key_bytes = {101, 110, 99, 114, 121, 112, 116, 101, 100, 46, 108, 117, 97}
local key = string.char(table.unpack(key_bytes))

local hex_data = ""

local function hex_to_bytes(hex)
    local bytes = {}
    for i = 1, #hex, 2 do
        local byte = tonumber(hex:sub(i, i+1), 16)
        if not byte then error("Invalid hex string") end
        bytes[#bytes + 1] = string.char(byte)
    end
    return table.concat(bytes)
end

local function decrypt(data, k)
    local bytes = {}
    local key_bytes = {k:byte(1, -1)}
    local key_len = #key_bytes
    local data_bytes = {data:byte(1, -1)}
    for i = 1, #data_bytes do
        bytes[i] = string.char(data_bytes[i] ~ key_bytes[(i - 1) % key_len + 1])
    end
    return table.concat(bytes)
end

local encrypted = hex_to_bytes(hex_data)
local decrypted = decrypt(encrypted, key)
local func, err = loadstring(decrypted)
if func then
    func()
else
    warn("Decryption failed:", err)
end
